// ───────────────────────────────────────────────────────────────────
// MODULE: Workflow Invariance
// ───────────────────────────────────────────────────────────────────

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';

const SKILL_ROOT = path.resolve(__dirname, '../../..');
const WORKSPACE_ROOT = path.resolve(SKILL_ROOT, '../../..');
const BANNED = /\b(preset|capabilit(?:y|ies)|kind|manifest)\b/iu;

interface SurfaceHit {
  surface: string;
  line: number;
  text: string;
}

function pathExists(filePath: string): boolean {
  return fs.existsSync(filePath);
}

function walk(startPath: string, predicate: (filePath: string) => boolean, results: string[] = []): string[] {
  if (!pathExists(startPath)) return results;
  // Scanner-scope guard: never descend into vendored node_modules. Those trees are gitignored
  // dependency code, not our public surface, and otherwise yield spurious dependency-README hits.
  if (startPath.split(/[\\/]/u).includes('node_modules')) return results;
  const stat = fs.statSync(startPath);
  if (stat.isFile()) {
    if (predicate(startPath)) results.push(startPath);
    return results;
  }
  for (const entry of fs.readdirSync(startPath)) {
    walk(path.join(startPath, entry), predicate, results);
  }
  return results;
}

function isTextSurface(filePath: string): boolean {
  return /\.(md|yaml|yml|json|txt)$/iu.test(filePath);
}

function relative(filePath: string): string {
  return path.relative(WORKSPACE_ROOT, filePath).replace(/\\/gu, '/');
}

function collectDefaultSurfaces(): string[] {
  const roots = [
    path.join(SKILL_ROOT, 'runtime/cli/tests/fixtures'),
    path.join(SKILL_ROOT, 'templates'),
    path.join(WORKSPACE_ROOT, '.skilled/command'),
    path.join(WORKSPACE_ROOT, '.skilled/agent'),
    path.join(SKILL_ROOT, 'feature-catalog'),
    path.join(SKILL_ROOT, 'manual-testing-playbook'),
  ];
  const files = roots.flatMap((root) => walk(root, isTextSurface));
  for (const name of ['CLAUDE.md', 'AGENTS.md', 'AGENTS_Barter.md', 'AGENTS_example_fs_enterprises.md']) {
    const filePath = path.join(WORKSPACE_ROOT, name);
    if (pathExists(filePath)) files.push(filePath);
  }
  files.push(path.join(SKILL_ROOT, 'SKILL.md'));
  return files;
}

function collectExtraSurfaces(): string[] {
  return (process.env.WORKFLOW_INVARIANCE_EXTRA_PATHS ?? '')
    .split(path.delimiter)
    .map((entry) => entry.trim())
    .filter(Boolean)
    .map((entry) => path.resolve(entry));
}

function isLegacyPhaseCleanupDebt(filePath: string): boolean {
  const rel = relative(filePath);
  return [
    'AGENTS.md',
    'AGENTS_Barter.md',
    'CLAUDE.md',
    '.skilled/agents/',
    '.skilled/commands/',
    '.skilled/skills/system-spec-kit/SKILL.md',
    '.skilled/skills/system-spec-kit/runtime/cli/tests/fixtures/phase-creation/',
  ].some((prefix) => rel === prefix || rel.startsWith(prefix));
}

function isAllowedHit(hit: SurfaceHit, filePath: string, isExtra: boolean): boolean {
  const rel = relative(filePath);
  if (rel.includes('.opencode/specs/')) return true;
  // Anchor-repair sample fixtures are frozen corpus data replayed verbatim by the repair test; their
  // vocabulary is the corpus's own, not text this skill publishes, and rewriting it would stop the
  // sample being faithful.
  if (hit.surface.startsWith('.skilled/skills/system-spec-kit/runtime/cli/tests/fixtures/anchor-repair-sample/')) return true;
  if (rel.endsWith('.skilled/skills/system-spec-kit/templates/CONTRACT.md')) return true;
  if (rel.endsWith('.skilled/skills/system-spec-kit/templates/EXTENSION-GUIDE.md')) return true;
  if (rel.endsWith('.skilled/skills/system-spec-kit/templates/MIGRATION.md')) return true;
  if (rel.endsWith('.skilled/skills/system-spec-kit/templates/spec-kit-docs.json')) return true;
  if (rel.endsWith('.skilled/skills/system-spec-kit/templates/README.md')) return true;
  if (/runtime\/lib\/config\/capability-flags\.ts|lib\/config\/capability-flags\.ts|\bcapability-flags\.ts\b|from ['"][^'"]*capability-flags['"]|require\(['"][^'"]*capability-flags(?:\.js)?['"]\)/iu.test(hit.text)) return true;
  if (!isExtra && isLegacyPhaseCleanupDebt(filePath)) return true;
  // --- Concrete technical identifiers that are never private taxonomy (schema fields, real
  // filenames/modules, MCP protocol) — allowed by the specific token they match, not by whole
  // surface, so an unrelated banned word on another line still fails. ---
  // Provenance schema: `source_kind` column / `source-kind` provenance attribute (schema v35).
  if (/source[_ -]kind/iu.test(hit.text)) return true;
  // Real manifest artifacts: `manifest.json`/`.tsv`/`.ts` files (incl. `*-manifest.json`), embedder
  // `manifest.{backend,dim,name}` fields, and the CHECKPOINT_MANIFEST / getManifest identifiers.
  if (/\bmanifest\.(?:json|tsv|ts|backend|dim|name)\b|\bgetManifest\b|\bCHECKPOINT_MANIFEST\b/u.test(hit.text)) return true;
  // Roadmap capability-flags config module/type + doc, the `opencode-goal-capabilities` test, and the
  // `capabilities` JSON-RPC / config field — MCP protocol + config surface, not workflow taxonomy.
  if (/capability-flags|MemoryRoadmapCapabilityFlags|roadmap capability flags|opencode-goal-capabilities|"capabilities"\s*:|capabilities\s*:\s*\{/iu.test(hit.text)) return true;
  // Compiled-routing serving authority: a hub's compiled activation manifest is a real
  // artifact and `missing-manifest` is a literal causeCode the status tool emits, so this
  // vocabulary is the system's own, not the private template taxonomy.
  if (/compiled activation manifest|missing-manifest|manifest or cohort state|manifest serving-authority|flag or manifest intentionally withholds/iu.test(hit.text)) return true;
  // Real env var naming a real on-disk artifact for recursive child coverage.
  if (/SPECKIT_CHILD_MANIFEST_FILE/u.test(hit.text)) return true;
  // /doctor router consolidation feature docs legitimately use "manifest" vocabulary (route
  // manifest + manifest-driven dispatch) — a real command surface, not private taxonomy.
  if (rel.endsWith('.skilled/skills/system-spec-kit/feature-catalog/maintenance/doctor-router-and-manifest-dispatch.md')) return true;

